import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_batchnorm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool training,
    double momentum,
    double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void bn_stats_kernel(
    const float* __restrict__ x,
    float* __restrict__ sum,
    float* __restrict__ sumsq,
    int N, int C, int H, int W)
{
    int c = blockIdx.x;
    int64_t HW = (int64_t)H * W;
    int64_t CHW = (int64_t)C * HW;
    int64_t perChannel = (int64_t)N * HW;

    Tensor gX = make_tensor(make_gmem_ptr(x),
                             make_shape(N, C, H, W),
                             make_stride(CHW, HW, (int64_t)W, Int<1>{}));

    extern __shared__ float sdata[];
    float* s_sum = sdata;
    float* s_sumsq = sdata + blockDim.x;

    int tid = threadIdx.x;
    int64_t start = (int64_t)blockIdx.y * blockDim.x + tid;
    int64_t stride = (int64_t)gridDim.y * blockDim.x;

    float local_sum = 0.f, local_sumsq = 0.f;
    for (int64_t idx = start; idx < perChannel; idx += stride) {
        int n = (int)(idx / HW);
        int64_t rem = idx % HW;
        int h = (int)(rem / W);
        int w = (int)(rem % W);
        float v = gX(n, c, h, w);
        local_sum += v;
        local_sumsq += v * v;
    }

    s_sum[tid] = local_sum;
    s_sumsq[tid] = local_sumsq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
            s_sumsq[tid] += s_sumsq[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicAdd(&sum[c], s_sum[0]);
        atomicAdd(&sumsq[c], s_sumsq[0]);
    }
}
__global__ void bn_stats_kernel_vec4(
    const float4* __restrict__ x4,
    float* __restrict__ sum,
    float* __restrict__ sumsq,
    int N, int C, int64_t HW4)
{
    int c = blockIdx.x;
    int64_t CHW4 = (int64_t)C * HW4;
    int64_t perChannel4 = (int64_t)N * HW4;
    extern __shared__ float sdata[];
    float* s_sum = sdata;
    float* s_sumsq = sdata + blockDim.x;
    int tid = threadIdx.x;
    int64_t start = (int64_t)blockIdx.y * blockDim.x + tid;
    int64_t stride = (int64_t)gridDim.y * blockDim.x;
    float local_sum = 0.f, local_sumsq = 0.f;
    for (int64_t idx = start; idx < perChannel4; idx += stride) {
        int n = (int)(idx / HW4);
        int64_t rem = idx % HW4;
        int64_t offset = (int64_t)n * CHW4 + (int64_t)c * HW4 + rem;
        float4 v4 = x4[offset];
        local_sum += v4.x + v4.y + v4.z + v4.w;
        local_sumsq += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
    }
    s_sum[tid] = local_sum;
    s_sumsq[tid] = local_sumsq;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
            s_sumsq[tid] += s_sumsq[tid + s];
        }
        __syncthreads();
    }
    if (tid == 0) {
        atomicAdd(&sum[c], s_sum[0]);
        atomicAdd(&sumsq[c], s_sumsq[0]);
    }
}

__global__ void bn_finalize_kernel(
    const float* __restrict__ sum,
    const float* __restrict__ sumsq,
    float* __restrict__ mean,
    float* __restrict__ var,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int C, int64_t count, float momentum, bool training)
{
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;

    float m = sum[c] / (float)count;
    float v = sumsq[c] / (float)count - m * m;
    if (v < 0.f) v = 0.f;
    mean[c] = m;
    var[c] = v;

    if (training) {
        float unbiased_var = (count > 1) ? v * (float)count / (float)(count - 1) : v;
        running_mean[c] = (1.f - momentum) * running_mean[c] + momentum * m;
        running_var[c]  = (1.f - momentum) * running_var[c]  + momentum * unbiased_var;
    }
}

__global__ void bn_normalize_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float eps,
    int N, int C, int H, int W)
{
    int64_t HW = (int64_t)H * W;
    int64_t CHW = (int64_t)C * HW;
    int64_t total = (int64_t)N * CHW;

    Tensor gX = make_tensor(make_gmem_ptr(x),
                             make_shape(N, C, H, W),
                             make_stride(CHW, HW, (int64_t)W, Int<1>{}));
    Tensor gY = make_tensor(make_gmem_ptr(y),
                             make_shape(N, C, H, W),
                             make_stride(CHW, HW, (int64_t)W, Int<1>{}));

    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x * blockDim.x;

    for (; idx < total; idx += stride) {
        int n = (int)(idx / CHW);
        int64_t rem = idx % CHW;
        int c = (int)(rem / HW);
        int64_t rem2 = rem % HW;
        int h = (int)(rem2 / W);
        int w = (int)(rem2 % W);

        float m = mean[c];
        float v = var[c];
        float inv_std = rsqrtf(v + eps);
        float val = gX(n, c, h, w);
        float norm = (val - m) * inv_std;
        gY(n, c, h, w) = norm * weight[c] + bias[c];
    }
}
__global__ void bn_normalize_kernel_vec4(
    const float4* __restrict__ x,
    float4* __restrict__ y,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float eps,
    int C, int64_t HW4, int64_t CHW4, int64_t total4)
{
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x * blockDim.x;
    for (; idx < total4; idx += stride) {
        int64_t rem = idx % CHW4;
        int c = (int)(rem / HW4);
        float m = mean[c];
        float v = var[c];
        float inv_std = rsqrtf(v + eps);
        float w_c = weight[c];
        float b_c = bias[c];
        float4 val = x[idx];
        float4 out;
        out.x = (val.x - m) * inv_std * w_c + b_c;
        out.y = (val.y - m) * inv_std * w_c + b_c;
        out.z = (val.z - m) * inv_std * w_c + b_c;
        out.w = (val.w - m) * inv_std * w_c + b_c;
        y[idx] = out;
    }
}

torch::Tensor cute_batchnorm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool training,
    double momentum,
    double eps)
{
