        atomicAdd(&sum[c], s_sum[0]);
        atomicAdd(&sumsq[c], s_sumsq[0]);
    }
}

__global__ void bn_finalize_kernel(
    const float* __restrict__ sum,
    const float* __restrict__ sumsq,
    float* __restrict__ mean,
    float* __restrict__ var,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int C, int64_t count, float momentum, bool training)
{
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;

    float m = sum[c] / (float)count;
    float v = sumsq[c] / (float)count - m * m;
    if (v < 0.f) v = 0.f;
    mean[c] = m;
    var[c] = v;

    if (training) {
        float unbiased_var = (count > 1) ? v * (float)count / (float)(count - 1) : v;
        running_mean[c] = (1.f - momentum) * running_mean[c] + momentum * m;
        running_var[c]  = (1.f - momentum) * running_var[c]  + momentum * unbiased_var;
    }
}

__global__ void bn_normalize_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float eps,
    int N, int C, int H, int W)
{
    int64_t HW = (int64_t)H * W;
    int64_t CHW = (int64_t)C * HW;
    int64_t total = (int64_t)N * CHW;

    Tensor gX = make_tensor(make_gmem_ptr(x),
                             make_shape(N, C, H, W),
                             make_stride(CHW, HW, (int64_t)W, Int<1>{}));
    Tensor gY = make_tensor(make_gmem_ptr(y),
                             make_shape(N, C, H, W),
                             make_stride(CHW, HW, (int64_t)W, Int<1>{}));

    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x * blockDim.x;

    for (; idx < total; idx += stride) {
        int n = (int)(idx / CHW);
        int64_t rem = idx % CHW;
        int c = (int)(rem / HW);
        int64_t rem2 = rem % HW;
        int h = (int)(rem2 / W);
        int w = (int)(rem2 % W);

        float m = mean[c];
        float v = var[c];
        float inv_std = rsqrtf(v + eps);
        float val = gX(n, c, h, w);
        float norm = (val - m) * inv_std;
        gY(n, c, h, w) = norm * weight[c] + bias[c];
    }
}
__global__ void bn_normalize_kernel_vec4(
    const float4* __restrict__ x,
    float4* __restrict__ y,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float eps,
    int C, int64_t HW4, int64_t CHW4, int64_t total4)
{
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x * blockDim.x;
    for (; idx < total4; idx += stride) {
        int64_t rem = idx % CHW4;
        int c = (int)(rem / HW4);
        float m = mean[c];
        float v = var[c];
        float inv_std = rsqrtf(v + eps);
        float w_c = weight[c];
        float b_c = bias[c];
        float4 val = x[idx];
        float4 out;
        out.x = (val.x - m) * inv_std * w_c + b_c;
        out.y = (val.y - m) * inv_std * w_c + b_c;
        out.z = (val.z - m) * inv_std * w_c + b_c;
        out.w = (val.w - m) * inv_std * w_c + b_c;
        y[idx] = out;
    }
}

torch::Tensor cute_batchnorm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool training,
    double momentum,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "expect float32 tensor");

    auto x_c = x.contiguous();
    auto weight_c = weight.contiguous();
    auto bias_c = bias.contiguous();
    auto running_mean_c = running_mean.contiguous();
    auto running_var_c = running_var.contiguous();

    int N = (int)x_c.size(0);
    int C = (int)x_c.size(1);
    int H = (int)x_c.size(2);
    int W = (int)x_c.size(3);

    auto y = torch::empty_like(x_c);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    torch::Tensor mean_t, var_t;

    if (training) {
        auto opts = x_c.options();
        auto sum_t = torch::zeros({C}, opts);
        auto sumsq_t = torch::zeros({C}, opts);
        mean_t = torch::empty({C}, opts);
        var_t = torch::empty({C}, opts);

        int64_t perChannel = (int64_t)N * H * W;
        int threads = 256;
        int64_t blocksPerChannelNeeded = (perChannel + threads - 1) / threads;
        int blocksY = (int)std::min<int64_t>(blocksPerChannelNeeded, 128);
        if (blocksY < 1) blocksY = 1;

        dim3 grid1(C, blocksY);
        size_t shmem = 2 * threads * sizeof(float);

        bn_stats_kernel<<<grid1, threads, shmem, stream>>>(
            x_c.data_ptr<float>(),
            sum_t.data_ptr<float>(),
            sumsq_t.data_ptr<float>(),
            N, C, H, W);

        int threads2 = 128;
        int blocks2 = (C + threads2 - 1) / threads2;
        bn_finalize_kernel<<<blocks2, threads2, 0, stream>>>(
            sum_t.data_ptr<float>(),
            sumsq_t.data_ptr<float>(),
            mean_t.data_ptr<float>(),
            var_t.data_ptr<float>(),
            running_mean_c.data_ptr<float>(),
            running_var_c.data_ptr<float>(),
            C, perChannel, (float)momentum, true);

        // write back updated running stats into original tensors if needed
        if (!running_mean.is_same(running_mean_c)) {
            running_mean.copy_(running_mean_c);
        }
        if (!running_var.is_same(running_var_c)) {
            running_var.copy_(running_var_c);
        }
    } else {
        mean_t = running_mean_c;
        var_t = running_var_c;
    }

    int64_t total = (int64_t)N * C * H * W;
    bool can_vec4 = ((H * W) % 4 == 0);
    if (can_vec4) {
        int64_t HW4 = (int64_t)H * W / 4;
        int64_t CHW4 = (int64_t)C * HW4;
        int64_t total4 = (int64_t)N * CHW4;
        int threads3 = 256;
        int64_t blocksNeeded = (total4 + threads3 - 1) / threads3;
        int blocks3 = (int)std::min<int64_t>(blocksNeeded, (int64_t)65535 * 32);
        if (blocks3 < 1) blocks3 = 1;
        bn_normalize_kernel_vec4<<<blocks3, threads3, 0, stream>>>(
            reinterpret_cast<const float4*>(x_c.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            mean_t.data_ptr<float>(),
            var_t.data_ptr<float>(),
            weight_c.data_ptr<float>(),
            bias_c.data_ptr<float>(),
            (float)eps,
            C, HW4, CHW4, total4);
    } else {
        int threads3 = 256;
        int64_t blocksNeeded = (total + threads3 - 1) / threads3;
        int blocks3 = (int)std::min<int64_t>(blocksNeeded, (int64_t)65535 * 32);
        if (blocks3 < 1) blocks3 = 1;
        bn_normalize_kernel<<<blocks3, threads3, 0, stream>>>(
            x_c.data_ptr<float>(),
            y.data_ptr<float>(),
            mean_t.data_ptr<float>(),
            var_t.data_ptr<float>(),
            weight_c.data_ptr<float>(),
            bias_c.data_ptr<float>(),
            (float)eps,
            N, C, H, W);
    }

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE batchnorm launch failed");
    return y;
}
